.cyber-switch {
  --width: 120px;
  --height: 220px;
  --border: 0px;
  --lever-height: 80px;
  --spacing: 20px;
  --on-color: #d69bd7;
  --off-color: #52b5e3;
  --glow-intensity: 0.2;

  width: var(--width);
  height: var(--height);
  position: relative;
  background: #000000;
  border: var(--border) solid #333;
  box-shadow:
    inset 0 0 10px #000,
    0 0 0 2px #000;
  margin: auto;
  overflow: hidden;
  font-family: "Courier New", monospace;
}

/* Status indicator bars - top (green) and bottom (red) */
.cyber-switch::before,
.cyber-switch::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  height: 5px;
  z-index: 3;
  transition: all 0.4s cubic-bezier(0.65, 0, 0.35, 1);
}

.cyber-switch::before {
  top: 0;
  background: var(--on-color);
  box-shadow: 0 0 15px var(--on-color);
  opacity: 1;
  transform: translateY(-10px);
}

.cyber-switch::after {
  bottom: 0;
  background: var(--off-color);
  box-shadow: 0 0 15px var(--off-color);
  opacity: 1;
  transform: translateY(10px);
}

/* Active states for indicator bars */
.cyber-switch input:checked ~ ::before {
  opacity: 1;
  transform: translateY(0);
}

.cyber-switch input:checked ~ ::after {
  opacity: 0;
  transform: translateY(10px);
}

.cyber-switch input:not(:checked) ~ ::before {
  opacity: 0;
  transform: translateY(-10px);
}

.cyber-switch input:not(:checked) ~ ::after {
  opacity: 1;
  transform: translateY(0);
}

/* Switch core styles */
.cyber-switch input {
  position: absolute;
  opacity: 0;
  width: 100%;
  height: 100%;
  cursor: crosshair;
  z-index: 10;
}

.cyber-switch .lever {
  position: absolute;
  width: calc(100% - var(--spacing) * 2);
  height: var(--lever-height);
  left: var(--spacing);
  background: #040404;
  border: 1px solid #040404;
  z-index: 2;
  transition:
    top 0.4s cubic-bezier(0.5, 1.8, 0.5, 1.2),
    transform 0.2s ease,
    box-shadow 0.4s,
    border-color 0.4s;
  display: flex;
  justify-content: center;
  align-items: center;
  overflow: hidden;
}

/* Shine animation */
.cyber-switch .lever::before {
  content: "";
  position: absolute;
  width: 100%;
  height: 100%;
  background: linear-gradient(
    90deg,
    transparent 45%,
    rgba(243, 160, 229, 0.116) 50%,
    transparent 55%
  );
  background-size: 200% 200%;
  animation: shine 3s linear infinite paused;
}

@keyframes shine {
  0% {
    background-position: -100% -100%;
  }
  100% {
    background-position: 100% 100%;
  }
}

/* Lever inner circle */
.cyber-switch .lever-inner {
  width: 50px;
  height: 50px;
  background: #000;
  border: 1px solid #3d6b86;
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  overflow: hidden;
  transition: all 0.4s;
}

/* Active state gradient */
.cyber-switch .lever-inner::before {
  content: "";
  position: absolute;
  width: 100%;
  height: 100%;
  background: conic-gradient(transparent, var(--on-color), transparent);
  opacity: 0;
  transition: opacity 0.4s;
}

/* O/1 text inside lever */
.cyber-switch .lever-inner::after {
  content: "0";
  position: absolute;
  color: var(--off-color);
  font-weight: bold;
  font-size: 24px;
  text-shadow: 0 0 4px var(--off-color);
  transition: all 0.4s;
}

/* 1 State */
.cyber-switch input:checked ~ .lever {
  top: var(--spacing);
  border-color: var(--on-color);
  box-shadow:
    0 0 20px var(--on-color),
    inset 0 0 10px var(--on-color);
}

.cyber-switch input:checked ~ .lever::before {
  animation-play-state: running;
}

.cyber-switch input:checked ~ .lever .lever-inner {
  border-color: var(--on-color);
}

.cyber-switch input:checked ~ .lever .lever-inner::before {
  opacity: 0.6;
}

.cyber-switch input:checked ~ .lever .lever-inner::after {
  content: "1";
  color: var(--on-color);
  text-shadow: 0 0 10px var(--on-color);
  font-size: 24px;
}

/* OFF State */
.cyber-switch input:not(:checked) ~ .lever {
  top: calc(100% - var(--lever-height) - var(--spacing));
  border-color: var(--off-color);
  box-shadow:
    0 0 1px var(--off-color),
    inset 0 0 10px var(--off-color);
}

/* Press effect */
.cyber-switch input:active ~ .lever {
  transform: scale(0.96);
}

.cyber-switch input:checked ~ .status {
  color: var(--on-color);
  text-shadow: 0 0 12px var(--on-color);
  transform: scale(1.05);
}

/* Circuit board lines */
.cyber-switch .circuit {
  position: absolute;
  width: 100%;
  height: 100%;
  top: 0;
  left: 0;
  pointer-events: none;
  z-index: 1;
}

.cyber-switch .circuit-line {
  position: absolute;
  background: #c2bfbf;
  transition: all 0.4s;
}

.cyber-switch .horizontal {
  width: 100%;
  height: 0.5px;
}

.cyber-switch .vertical {
  width: 1px;
  height: 100%;
}

.cyber-switch .circuit-line:nth-child(1) {
  top: 25%;
}

.cyber-switch .circuit-line:nth-child(2) {
  top: 75%;
}

.cyber-switch .circuit-line:nth-child(3) {
  left: 25%;
}

.cyber-switch .circuit-line:nth-child(4) {
  left: 75%;
}

/* Circuit line activation */
.cyber-switch input:checked ~ .circuit .circuit-line {
  background: var(--on-color);
  box-shadow: 0 0 5px var(--on-color);
  height: 1px;
  width: 1px;
}

.cyber-switch input:not(:checked) ~ .circuit .circuit-line {
  background: var(--off-color);
  box-shadow: 0 0 5px var(--off-color);
}

/* Power burst effect */
.cyber-switch .power-burst {
  position: absolute;
  width: 100%;
  height: 100%;
  top: 0;
  left: 0;
  background: radial-gradient(
    circle at center,
    transparent 60%,
    var(--on-color) 100%
  );
  opacity: 0;
  transition: opacity 0.3s;
  pointer-events: none;
  z-index: 0;
}

.cyber-switch input:active ~ .power-burst {
  opacity: 0.3;
  transition: none;
}
